mapper.insert:
INSERT INTO access_grant (id, account_id, partner_id, permission, granted_by, granted_at, revoked_at)
SELECT #{id}, a.id, #{partnerId}, #{permission}, #{grantedBy}, #{grantedAt}, #{revokedAt}
FROM account a WHERE a.id = #{accountId} AND a.customer_id = #{grantedBy}

mapper.select:
SELECT g.id, g.account_id, g.partner_id, g.permission, g.granted_by, g.granted_at, g.revoked_at
FROM access_grant g JOIN account a ON a.id = g.account_id
WHERE g.id = #{grantId} AND g.account_id = #{accountId} AND a.customer_id = #{customerId}

mapper.update:
UPDATE access_grant g SET revoked_at = #{revokedAt}
FROM account a
WHERE a.id = g.account_id AND a.customer_id = #{customerId}
  AND g.id = #{grantId} AND g.account_id = #{accountId} AND g.revoked_at IS NULL
  AND CAST(#{revokedAt} AS TIMESTAMPTZ) IS NOT NULL
